            "key_concepts": [
              {
                "term": "Sistema experto",
                "def": "Programa que emula el razonamiento de un especialista; base de conocimiento, memoria de trabajo, motor de inferencia y módulo de explicación."
              },
              {
                "term": "Módulo de explicación",
                "def": "Registra la traza de inferencia; permite responder «¿por qué llegaste a esa conclusión?»."
              },
              {
                "term": "Factor de certeza (CF)",
                "def": "Valor entre −1 y +1 de MYCIN que expresa confianza en una hipótesis."
              },
              {
                "term": "Lógica difusa",
                "def": "Zadeh, 1965; grados de pertenencia entre 0 y 1."
              },
              {
                "term": "Limitaciones de los SE",
                "def": "Escalabilidad, mantenimiento, adquisición de conocimiento (tácito) y fragilidad ante lo inesperado."
              },
              {
                "term": "Fuentes de incertidumbre",
                "def": "Observabilidad parcial, estocasticidad, ignorancia causal, complejidad computacional."
              },
              {
                "term": "Epistémica vs. aleatoria",
                "def": "Falta de información (reducible) vs. propia del fenómeno (irreducible)."
              },
              {
                "term": "Datos faltantes",
                "def": "Tres casos; el peor: falta justamente por un valor extremo."
              },
              {
                "term": "Frecuentista vs. bayesiana",
                "def": "Frecuencia relativa en repeticiones vs. grado de conocimiento actualizable."
              },
              {
                "term": "Axiomas de probabilidad",
                "def": "No negatividad; P(espacio muestral) = 1; aditividad para eventos excluyentes."
              },
              {
                "term": "Teorema de Bayes",
                "def": "Posterior ∝ verosimilitud × a priori; Thomas Bayes (≈1763) y Laplace."
              },
              {
                "term": "MAP",
                "def": "Maximum A Posteriori: valor más probable dada la evidencia."
              },
              {
                "term": "Red bayesiana",
                "def": "Grafo dirigido acíclico; nodos = variables; aristas = dependencias; tablas de probabilidad condicional."
              },
              {
                "term": "Inferencia en redes",
                "def": "Predictiva (causas→efectos), diagnóstica (efectos→causas), intercausal."
              },
              {
                "term": "Ontología",
                "def": "Especificación explícita de los conceptos de un dominio que permite razonamiento automático."
              },
              {
                "term": "RDF / SPARQL / OWL",
                "def": "Tripletas con URI / lenguaje de consulta / ontologías con lógica formal e inferencia por jerarquías."
              },
              {
                "term": "IA híbrida",
                "def": "Integra simbólico + aprendizaje + probabilístico; patrones: cascada, conocimiento durante el aprendizaje, herramientas, ajuste fino."
              }
            ],
